# Benchmark Xavier memory search performance# Measures: latency, recall@k, relevance, throughput$ErrorActionPreference = "Continue"$XAVIER_URL = "http://localhost:8006"$TOKEN = "dev-token"$HEADERS = @{ "Content-Type" = "application/json"; "X-Xavier-Token" = $TOKEN }Write-Host "=== Xavier Memory Benchmark ==="Write-Host "Target: $XAVIER_URL/memory/search"Write-Host ""# Verify Xaviertry {    $health = Invoke-RestMethod -Uri "$XAVIER_URL/health" -Method Get -ErrorAction Stop    Write-Host "âœ… Xavier OK" -ForegroundColor Green} catch {    Write-Host "âŒ Xavier NOT RESPONDING" -ForegroundColor Red    exit 1}# --- Test Queries (should match indexed content) ---$testQueries = @(    @{ query = "gobernanza token votacion consejo xavier core"; tags = @("governance") }    @{ query = "wallet post-cuantica ML-KEM ML-DSA firma digital"; tags = @("wallet") }    @{ query = "data commons funnel reputation recompensas"; tags = @("data-commons") }    @{ query = "memoria RAG busqueda indexacion openclaw"; tags = @("memory") }    @{ query = "xavier data commons architecture features roadmap"; tags = @("data-commons", "architecture") }    @{ query = "configuracion bridge sincronizacion sesiones"; tags = @("config") }    @{ query = "compilacion rust error borrow checker fix"; tags = @("code") }    @{ query = "token supply limit 1 billon distribucion"; tags = @("wallet", "tokenomics") }    @{ query = "benchmark performance latencia throughput"; tags = @("testing") }    @{ query = "reputation proof contribution staked slashing"; tags = @("reputation") })$results = @()Write-Host "Running $($testQueries.Count) benchmark queries...`n" -ForegroundColor Cyanforeach ($tq in $testQueries) {    $payload = @{        query = $tq.query        limit = 5    } | ConvertTo-Json -Compress    $start = Get-Date    try {        $resp = Invoke-RestMethod -Uri "$XAVIER_URL/memory/search" -Method Post -Body $payload -ContentType "application/json" -Headers $HEADERS -ErrorAction Stop        $elapsed = ((Get-Date) - $start).TotalMilliseconds        $resultCount = 0        $hasRelevant = $false        if ($resp.results -and $resp.results -is [System.Array]) {            $resultCount = $resp.results.Count            # Check if any result contains expected tag keywords            $allContent = ($resp.results | ForEach-Object { $_.content }) -join " "            foreach ($tag in $tq.tags) {                if ($allContent -match $tag) { $hasRelevant = $true; break }            }        }        $results += @{            query = $tq.query.Substring(0, [Math]::Min($tq.query.Length, 60))            latencyMs = [math]::Round($elapsed, 1)            numResults = $resultCount            relevant = $hasRelevant            status = "OK"        }        Write-Host "  âœ… '$($tq.query.Substring(0,40))...' â†’ ${resultCount} results in ${elapsed:N1}ms $(if($hasRelevant){'ðŸŽ¯'}else{'âš ï¸'})" -ForegroundColor $(if($hasRelevant){"Green"}else{"Yellow"})    } catch {        $elapsed = ((Get-Date) - $start).TotalMilliseconds        $results += @{            query = $tq.query.Substring(0, [Math]::Min($tq.query.Length, 60))            latencyMs = [math]::Round($elapsed, 1)            numResults = 0            relevant = $false            status = "ERROR: $_"        }        Write-Host "  âŒ '$($tq.query.Substring(0,40))...' FAILED in ${elapsed:N1}ms : $_" -ForegroundColor Red    }    # Small delay between queries    Start-Sleep -Milliseconds 100}# --- Summary Stats ---Write-Host "`n==============================" -ForegroundColor CyanWrite-Host "BENCHMARK RESULTS" -ForegroundColor YellowWrite-Host "==============================" -ForegroundColor Cyan$okResults = $results | Where-Object { $_.status -eq "OK" }$failResults = $results | Where-Object { $_.status -ne "OK" }$avgLatency = if ($okResults.Count -gt 0) { ($okResults | Measure-Object -Property latencyMs -Average).Average } else { 0 }$minLatency = if ($okResults.Count -gt 0) { ($okResults | Measure-Object -Property latencyMs -Minimum).Minimum } else { 0 }$maxLatency = if ($okResults.Count -gt 0) { ($okResults | Measure-Object -Property latencyMs -Maximum).Maximum } else { 0 }$totalResults = ($okResults | Measure-Object -Property numResults -Sum).Sum$relevantCount = ($okResults | Where-Object { $_.relevant }).CountWrite-Host "Total queries: $($testQueries.Count)"Write-Host "Successful: $($okResults.Count)"Write-Host "Failed: $($failResults.Count)"Write-Host "Avg latency: $([math]::Round($avgLatency, 1))ms"Write-Host "Min latency: $([math]::Round($minLatency, 1))ms"Write-Host "Max latency: $([math]::Round($maxLatency, 1))ms"Write-Host "Total results returned: $totalResults"Write-Host "Relevant results: $relevantCount / $($okResults.Count) ($([math]::Round($relevantCount/$okResults.Count*100, 1))% recall)"Write-Host "Avg results per query: $([math]::Round($totalResults / [Math]::Max($okResults.Count, 1), 1))"# Perf gradeif ($avgLatency -lt 100) { $latencyGrade = "A+ ðŸš€" }elseif ($avgLatency -lt 300) { $latencyGrade = "A âœ…" }elseif ($avgLatency -lt 500) { $latencyGrade = "B âš¡" }elseif ($avgLatency -lt 1000) { $latencyGrade = "C ðŸ¢" }else { $latencyGrade = "D âŒ" }if ($relevantCount / [Math]::Max($okResults.Count, 1) -ge 0.8) { $recallGrade = "A ðŸŽ¯" }elseif ($relevantCount / [Math]::Max($okResults.Count, 1) -ge 0.5) { $recallGrade = "B ðŸ”" }elseif ($relevantCount / [Math]::Max($okResults.Count, 1) -ge 0.3) { $recallGrade = "C ðŸ‘€" }else { $recallGrade = "D â“" }Write-Host "`n--- Grades ---" -ForegroundColor CyanWrite-Host "ðŸŽï¸  Latency: $latencyGrade ($([math]::Round($avgLatency,1))ms avg)"Write-Host "ðŸŽ¯ Recall: $recallGrade ($([math]::Round($relevantCount/$okResults.Count*100,1))%)"# --- Per-query breakdown ---Write-Host "`n--- Per-Query Breakdown ---" -ForegroundColor Cyan$results | ForEach-Object {    $marker = if ($_.status -eq "OK") { "âœ…" } else { "âŒ" }    $relev = if ($_.relevant) { "ðŸŽ¯" } else { "âš ï¸" }    Write-Host "$marker [$($_.latencyMs)ms][$($_.numResults) results]$relev $($_.query)"    if ($_.status -ne "OK") {        Write-Host "       Error: $($_.status)" -ForegroundColor Red    }}# Save results$reportPath = "E:\scripts-python\xavier\benchmark_results.json"$resultsObj = @{    timestamp = (Get-Date -Format "o")    queries = $results    summary = @{        totalQueries = $testQueries.Count        successful = $okResults.Count        failed = $failResults.Count        avgLatencyMs = [math]::Round($avgLatency, 1)        minLatencyMs = [math]::Round($minLatency, 1)        maxLatencyMs = [math]::Round($maxLatency, 1)        totalResults = $totalResults        relevantResults = $relevantCount        recallRate = [math]::Round($relevantCount / [Math]::Max($okResults.Count, 1), 3)        latencyGrade = $latencyGrade        recallGrade = $recallGrade    }} | ConvertTo-Json -Depth 5$resultsObj | Out-File -FilePath $reportPath -Encoding utf8Write-Host "`nðŸ“Š Results saved to: $reportPath"